cd /tmp/sobre-bench-work/run-1f783cb9679e/data; grep "costsync.diff" cost-sync.log | grep -v added | python3 -I -c "
import sys,re,datetime as D
last={};
for l in sys.stdin:
    m=re.match(r'\[(\S+?)\.\d+\+00:00\].*case (\d+) classic (\d+) -> (\d+)',l)
    t=D.datetime.fromisoformat(m[1]);c=m[2];a,b=int(m[3]),int(m[4])
    if c in last and (t-last[c]).total_seconds()>3.5*3600: print(c,'gap',last[c],'->',t,a,b)
    last[c]=t
" | head -30; grep -c "classic.*->" cost-sync.log; grep "costsync.diff" cost-sync.log | awk '{split($0,a,"classic ");split(a[2],b," -> ");if(b[2]<b[1])print}' | head

